// Draws the game's splash into buf (S x S, rows as the title renderer uses
// them); returns false when the game has none.
function drawSplashImage(buf, S, name) {
  if (IMAGES[name]) {
    if (!decoded[name]) { const raw = Buffer.from(IMAGES[name], 'base64'); decoded[name] = new Float32Array(raw.length); for (let i = 0; i < raw.length; i++) decoded[name][i] = raw[i] / 255; }
    const d = decoded[name];
    for (let y = 0; y < S; y++) for (let x = 0; x < S; x++) { const i = (y * S + x) * 3, j = (Math.min(63, y) * 64 + Math.min(63, x)) * 3; buf[i] = d[j] || 0; buf[i + 1] = d[j + 1] || 0; buf[i + 2] = d[j + 2] || 0; }
    return true;
  }
  const L = LOGOS[name];
  if (L) {
    for (let i = 0; i < S * S; i++) { buf[i * 3] = L.bg[0]; buf[i * 3 + 1] = L.bg[1]; buf[i * 3 + 2] = L.bg[2]; }
    for (let k = 0; k < L.px.length; k += 5) { const x = L.px[k], y = L.px[k + 1]; if (x < 0 || y < 0 || x >= S || y >= S) continue; const i = (y * S + x) * 3; buf[i] = L.px[k + 2] / 15; buf[i + 1] = L.px[k + 3] / 15; buf[i + 2] = L.px[k + 4] / 15; }
    return true;
  }
  return false;
}

